SELECT id, customer_id, balance, MAX(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_balance, MIN(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_balance, AVG(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_balance, SUM(balance) OVER (PARTITION BY customer_id, account_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_sum_balance FROM accounts
